INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 19, 'theory', 'Network Attacks and Defense: Spoofing, DoS, MITM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 0, 'What does an attacker do in ARP spoofing?', '["Guesses passwords", "Overloads the link", "Sends forged ARP replies so that other people''s traffic flows through the attacker''s MAC", "Replaces a certificate"]', 2, 'ARP does not authenticate replies: the receiver believes the message "this IP is my MAC."');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 1, 'Which measure protects a server from a SYN flood?', '["Turn off encryption", "Enable SYN cookies: the server keeps no state until the handshake is confirmed", "Increase the MTU", "Close port 53"]', 1, 'SYN cookies encode the state in the reply''s sequence number, so the queue of half-open connections does not overflow.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 2, 'Why are open DNS resolvers dangerous for third parties?', '["They are not", "They read email", "They break certificates", "They are used to amplify DDoS: a short request in the victim''s name turns into a long reply"]', 3, 'Amplification is one kind of volumetric attack; resolvers should be closed to outsiders.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 3, 'What is the main defense against a man-in-the-middle (MITM) attack?', '["Encryption with verification of the server''s identity by a certificate", "Hiding the MAC address", "Increasing the speed", "Turning off DHCP"]', 0, 'Even if the traffic passes through the attacker, the attacker sees only ciphertext and cannot forge the certificate.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 19, 4, 'Which setting most quickly reduces the success of SSH password guessing?', '["Hide the server version", "Open an additional port", "Key-only login and lockout after several failures", "Turn off the firewall"]', 2, 'Keys make guessing pointless, and lockout damps the remaining attempts.');
